INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-five-ways', 'door', 'The Five Ways', 'A low crossing with a door on every side. The scullery''s damp comes in from one of them and the kennels'' smell from another, the gallery and the great hall open off two more, and a stair goes down to the forge. The flags are worn into a shallow dish in the middle by a garrison that went everywhere through here and never once stopped to stand in it.', 0, 0, 'upper', 0, 0, 32);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-five-ways', 'east', 'hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-five-ways', 'west', 'scullery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-five-ways', 'south', 'kennels', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-five-ways', 'north', 'gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-five-ways', 'down', 'forge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('hall', 'west', 'the-five-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('scullery', 'east', 'the-five-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('kennels', 'north', 'the-five-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('gallery', 'south', 'the-five-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('forge', 'up', 'the-five-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('guardroom', 'east', 'the-watch-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('library', 'east', 'the-roll-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-watch-passage', 'door', 'The Watch Passage', 'A narrow passage behind the guardroom, built for one man walking his round. There is a lamp-niche at shoulder height every ten paces, each with a black tongue of soot up the stone above it, and not one lamp left in any of them. The round went this way so many times that the floor has a path worn down its middle.', 0, 0, 'upper', 0, 3, 29);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-watch-passage', 'west', 'guardroom', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-watch-passage', 'north', 'the-quartermasters-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-watch-passage', 'south', 'the-roll-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-roll-room', 'door', 'The Roll Room', 'A clerk''s room off the library, lined floor to ceiling with pigeon-holes, each one holding a fat roll gone to felt in the damp. They are the muster rolls: who was on the strength, who was paid, who was issued what. Somebody pulled a handful out and dropped them, and they lie where they fell, every one unrolled to its last page.', 0, 0, 'upper', 0, 3, 30);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roll-room', 'west', 'library', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roll-room', 'north', 'the-watch-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roll-room', 'east', 'the-pay-table', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quartermasters-room', 'door', 'The Quartermaster''s Room', 'A cramped office with a high desk and a stool still pushed in under it. The ledger on the desk has been cut out of its binding, every page of it, and taken. Whoever stood at this desk last took the accounts with them and left the room exactly as it was.', 0, 0, 'upper', 0, 3, 28);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quartermasters-room', 'south', 'the-watch-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quartermasters-room', 'east', 'the-long-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-long-store', 'door', 'The Long Store', 'A long, low store with bays down one wall, each bay under its painted board: blankets, boots, cloaks, tallow. The bays are empty to the stone. Grain dust lies in the corners where sacks were dragged out, and the drag marks all run the same way, toward the door.', 0, 0, 'upper', 0, 4, 28);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-store', 'west', 'the-quartermasters-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-store', 'east', 'the-harness-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-harness-room', 'door', 'The Harness Room', 'Saddle-trees on wooden pegs, and bridle-hooks in rows above them, every hook bare. The smell of old leather hangs on with nothing left in the room to make it. One stirrup lies on the floor where it was dropped, and nobody came back for it.', 0, 0, 'upper', 0, 5, 28);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-harness-room', 'west', 'the-long-store', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-harness-room', 'east', 'the-fletchery', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fletchery', 'door', 'The Fletchery', 'Benches down both walls, and a floor gone soft underfoot with a century of feather-down and shavings. Bundles of shafts stood against the far wall; their outlines are still there, pale on the stone. There is no arrow in the room, not even a broken one. They were the first thing taken.', 0, 0, 'upper', 0, 6, 28);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fletchery', 'west', 'the-harness-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fletchery', 'south', 'the-arming-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-arming-passage', 'door', 'The Arming Passage', 'A wide passage made for men moving four abreast in kit, and both walls are scraped pale at hip height where scabbards and shield-rims dragged along the stone. It runs from the stores to the armoury door. Every scrape on it was made going the one way, out.', 0, 0, 'upper', 0, 6, 29);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arming-passage', 'north', 'the-fletchery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arming-passage', 'south', 'armory', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pay-table', 'door', 'The Pay Table', 'A bare room with a long table bolted to the floor and an iron grille across the middle of it, the paymaster''s side and the soldier''s side. The coin-box on the paymaster''s side is sprung and empty. On the soldier''s side the stone is dished in front of the grille, from men standing to be paid, one at a time, for years.', 0, 0, 'upper', 0, 4, 30);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pay-table', 'west', 'the-roll-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pay-table', 'east', 'the-sergeants-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sergeants-room', 'door', 'The Sergeants'' Room', 'Four cots, a table, and a rack for four sets of kit, all of it empty. The cots are made, the blankets squared and tucked, which is the only order left anywhere in this part of the fortress. Whoever made them expected to come back and sleep in them.', 0, 0, 'upper', 0, 5, 30);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sergeants-room', 'west', 'the-pay-table', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sergeants-room', 'east', 'armory', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('armory', 'north', 'the-arming-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('armory', 'west', 'the-sergeants-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-warren', 'east', 'the-side-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dripping-gallery', 'east', 'the-wet-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-side-run', 'door', 'The Side-Run', 'A run off the Rat-Warren just high enough to go along bent double, its floor polished smooth by bodies. The walls are greasy at rat height, a dark band along both sides, and the band goes on ahead into the dark further than you can see.', 0, 0, 'upper', 0, 3, 40);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-side-run', 'west', 'the-rat-warren', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-side-run', 'east', 'the-litter-chamber', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-litter-chamber', 'door', 'The Litter Chamber', 'A round hollow lined with shredded cloth, straw and hair, packed down into a nest the size of a cart. It is warm in here, warmer than earth has any business being, and the warmth is coming up out of the nest.', 0, 0, 'upper', 0, 4, 40);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-litter-chamber', 'west', 'the-side-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-litter-chamber', 'east', 'the-root-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-litter-chamber', 'south', 'the-scrape', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-root-hall', 'door', 'The Root Hall', 'The roof of the warren is roots here: a whole tree''s worth come down through the earth from somewhere far above and spread out flat, a ceiling of ropes. Things have been carried up and wedged in among them, and the floor underneath is bones.', 0, 0, 'upper', 0, 5, 40);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hall', 'west', 'the-litter-chamber', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hall', 'south', 'the-old-adit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scrape', 'door', 'The Scrape', 'A low stretch where the floor is all claw-marks, cut and recut into the clay until there is no flat left in it. Everything that goes deeper goes through here, and goes through fast.', 0, 0, 'upper', 0, 4, 41);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scrape', 'north', 'the-litter-chamber', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scrape', 'east', 'the-old-adit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scrape', 'south', 'the-fallen-props', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-adit', 'door', 'The Old Adit', 'Squared timbers, black and furred with mould, hold up a cut that men made: a sapper''s adit driven toward the fortress walls and given up. The rats found it and took it over. Their runs come in through its sides at every height.', 0, 0, 'upper', 0, 5, 41);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-adit', 'north', 'the-root-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-adit', 'west', 'the-scrape', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-adit', 'east', 'the-blind-heading', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-adit', 'south', 'the-hoard-hole', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-blind-heading', 'door', 'The Blind Heading', 'The adit''s last few yards, where the digging stopped. The face is still marked with the pick, and a shovel blade lies rusted into the floor at its foot. The air does not move here at all. Nobody finished this, and nobody will.', 0, 0, 'upper', 0, 6, 41);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blind-heading', 'west', 'the-old-adit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wet-run', 'door', 'The Wet Run', 'A run off the Dripping Gallery where water comes down the walls in sheets and the floor is a channel of black mud. Small prints go along it both ways, hundreds of them, and something larger has dragged through them all and left a trench.', 0, 0, 'upper', 0, 3, 42);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-run', 'west', 'the-dripping-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-run', 'east', 'the-fallen-props', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fallen-props', 'door', 'The Fallen Props', 'The old mine timbers have given way here, and the props lie across the passage at every angle like a dropped bundle of sticks. You go through over and under them. The roof they were holding is mostly still up.', 0, 0, 'upper', 0, 4, 42);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-props', 'west', 'the-wet-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-props', 'north', 'the-scrape', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-props', 'east', 'the-hoard-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-props', 'south', 'the-warren-sump', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hoard-hole', 'door', 'The Hoard-Hole', 'A pocket dug into the side of the run and packed with things carried here from somewhere else: buttons, a spoon, a buckle, a key-ring with no keys on it, teeth, a heap of whatever once shone. It has been added to for a very long time, and it is still being added to.', 0, 0, 'upper', 0, 5, 42);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hoard-hole', 'west', 'the-fallen-props', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hoard-hole', 'north', 'the-old-adit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warren-sump', 'door', 'The Black Sump', 'The lowest point of the runs, where their water comes to stand. It is black and still and smells of iron, and it fills the floor wall to wall. Bones show white just under the surface, close enough to touch, and none of them are small.', 0, 0, 'upper', 0, 4, 43);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warren-sump', 'north', 'the-fallen-props', NULL);
